<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$pageTitle='Vendas';$q=trim($_GET['q']??'');$from=$_GET['de']??'';$to=$_GET['ate']??'';$sql='SELECT v.*,c.nome cliente,u.nome usuario_nome FROM vendas v LEFT JOIN clientes c ON c.id=v.cliente_id JOIN usuarios u ON u.id=v.usuario_id WHERE (v.numero LIKE ? OR COALESCE(c.nome,\'\') LIKE ?)';$args=["%$q%","%$q%"];if($from){$sql.=' AND date(v.data_venda)>=?';$args[]=$from;}if($to){$sql.=' AND date(v.data_venda)<=?';$args[]=$to;}$sql.=' ORDER BY v.id DESC';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$pdo->prepare("UPDATE vendas SET status='Cancelada' WHERE id=? AND status='Concluida'")->execute([$id]);log_action('cancelamento de venda','vendas',$id);flash('success','Venda cancelada no histórico. O ajuste físico deve ser feito pelo módulo de estoque conforme a conferência.');redirect('index.php');}include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><h1>Vendas</h1><a class="btn primary" href="<?=e(app_url('/admin/pdv/index.php'))?>">＋ Nova venda</a></div><div class="card"><form class="search-row"><input name="q" value="<?=e($q)?>" placeholder="Número ou cliente"><input type="date" name="de" value="<?=e($from)?>"><input type="date" name="ate" value="<?=e($to)?>"><button class="btn secondary">Filtrar</button></form></div><div class="card" style="margin-top:16px"><div class="table-wrap"><table class="table"><thead><tr><th>Nº</th><th>Data</th><th>Cliente</th><th>Pagamento</th><th>Parcelas</th><th>Desconto</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['numero'])?></td><td><?=datetime_br($r['data_venda'])?></td><td><?=e($r['cliente']?:'—')?></td><td><?=e($r['forma_pagamento'])?></td><td><?=e($r['parcelas'])?>x</td><td><?=money($r['desconto'])?></td><td><?=money($r['total'])?></td><td><?=status_badge($r['status'])?></td><td class="nowrap"><a class="btn small secondary" href="<?=e(app_url('/admin/pdv/comprovante.php'))?>?id=<?=$r['id']?>">Abrir</a><?php if($r['status']==='Concluida'): ?><form style="display:inline" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small danger" onclick="return confirmAction('Cancelar esta venda no histórico?')">Cancelar</button></form><?php endif;?></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="9" class="empty">Nenhuma venda encontrada.</td></tr><?php endif;?></tbody></table></div></div><?php include __DIR__.'/../../includes/footer.php'; ?>
